extension Fuzz {
private class IndentationStripper: SyntaxRewriter {
  override func visit(_ token: TokenSyntax) -> TokenSyntax {
    if token.leadingTrivia.contains(where: \.isNewline)
|| token.trailingTrivia.contains(where: \.isNewline) {
      return
        token
.with(\.leadingTrivia, token. /* c */ leadingTrivia.removingIndentation)
        .with(\.trailingTrivia, token.trailingTrivia.removingIndentation)
    } else {
      return token
    }
  }
}
}
